        line = lines[i]
        if line.startswith("+++ "):
            raw = line[4:].strip()
            if raw.startswith("b/"):
                current_path = raw[2:].replace("\\", "/")
            elif raw == "/dev/null":
                current_path = None
            else:
                current_path = raw.replace("\\", "/")
            i += 1
            continue
        m = re.match(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@", line)
        if m and current_path:
            new_line = int(m.group(3))
            i += 1
            while i < n:
                hline = lines[i]
                if hline.startswith("diff --git "):
                    break
                if hline.startswith("--- ") and i + 1 < n and lines[i + 1].startswith("+++ "):
                    break
                if re.match(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@", hline):
                    break
                if hline.startswith("\\"):
                    i += 1
                    continue
                if not hline:
                    i += 1
                    continue
                op = hline[0]
                if op == "+":
                    touched[current_path].add(new_line)
                    new_line += 1
                elif op == "-":
                    pass
                elif op == " ":
                    new_line += 1
                else:
                    new_line += 1
                i += 1
